          html: String.raw`<p><b>Паронимы</b> — однокоренные слова одной части речи, похожие по звучанию, но различающиеся значением: <i>абонент — абонемент</i>, <i>эффектный — эффективный</i>.</p>
<p>В <b>задании 5 ЕГЭ</b> дано пять предложений с выделенными словами. В одном слово употреблено неверно — его нужно заменить паронимом и записать исправленное слово. Все пары берутся из <b>словника паронимов ФИПИ</b>.</p>
<div class="rule">Алгоритм: 1) к каждому выделенному слову подберите пароним; 2) подумайте, с какими словами сочетается каждый (надеть <b>что</b>, одеть <b>кого</b>); 3) найдите слово, которое «не встало» в контекст.</div>
<div class="tip">Суффикс часто подсказывает значение: <b>-ическ-</b> — «относящийся к…» (экономический кризис), <b>-ичн-</b> — «обладающий качеством» (экономичный двигатель), <b>-н-</b> у «экономный» — о человеке, который бережёт ресурсы.</div>`
