          h: 'Суффиксы существительных',
          html: String.raw`<div class="rule"><b>-чик- / -щик-.</b> После букв <b>д, т, з, с, ж</b> пишется <b>-чик-</b> (разведчик, лётчик, заказчик, разносчик). После остальных — <b>-щик-</b> (каменщик, сварщик, барабанщик, стекольщик).</div>
<div class="rule"><b>-ек- / -ик-.</b> Склоните слово: если гласная <b>выпадает</b> — <b>-ек-</b> (замочек — замочка, кусочек — кусочка); если <b>сохраняется</b> — <b>-ик-</b> (ключик — ключика, стульчик — стульчика).</div>
<div class="trap"><b>Ловушка.</b> Ударение здесь не помогает: нужно поставить слово в родительный падеж и посмотреть, осталась ли гласная.</div>
<div class="quick" data-a="ч">Вставьте букву: рассказ…ик (ч или щ).</div>`
