<div class="example"><p><b>Разбор.</b> «завис…щий»: инфинитив <i>зависеть</i> — исключение, II спряжение → <b>-ящ-</b>: зависящий. «Се…щий»: <i>сеять</i> — I спряжение → <b>-ющ-</b>: сеющий.</p></div>
